mapper.select:
SELECT s_start.id AS departureStationId, -- 出发站ID s_end.id AS arrivalStationId, -- 到达站ID s_start.name AS departure, -- 出发站名称 s_end.name AS arrival, -- 到达站名称 s_start.code AS departureCode, -- 出发站编码 s_end.code AS arrivalCode, -- 到达站编码 tss_a.departure_time AS departureTime, -- 出发时间 tss_b.arrival_time AS arrivalTime, -- 到达时间 tss_a.sequence AS startSequence, -- 出发站站序 tss_b.sequence AS endSequence, -- 到达站站序 t.id AS trainId, -- 列车ID t.train_number AS trainNumber, -- 列车车次 t.days_arrived AS daysArrived, -- 到达天数 t.sale_time AS saleTime, -- 可售时间 t.sale_status AS saleStatus -- 可售状态 FROM train_stop_station tss_a -- 先取出发站经停记录 INNER JOIN train_stop_station tss_b ON tss_a.train_id = tss_b.train_id AND tss_a.sequence < tss_b.sequence -- 先关联同一列车的到达站经停记录 INNER JOIN station s_start ON tss_a.station_id = s_start.id -- 再关联出发站信息 INNER JOIN station s_end ON tss_b.station_id = s_end.id -- 最后关联到达站信息 INNER JOIN train t ON tss_a.train_id = t.id -- 关联列车信息
AND s_start.code IN
#{departureCode}
AND s_end.code IN
#{arrivalCode}
AND EXISTS ( SELECT 1 FROM train_train_type ttt WHERE ttt.train_id = t.id AND ttt.type_id IN
#{typeId}
)
AND EXISTS ( SELECT 1 FROM train_seat_class tsc INNER JOIN seat_class sc ON tsc.seat_class_id = sc.id WHERE tsc.train_id = t.id -- 关联当前列车 AND sc.type IN
#{seatType}
)
AND DATE(tss_a.departure_time) = #{departureDate}
